'use strict';
(()=>{
 const D=window.GameData,T=window.CardTraits,V=window.CardVisuals,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Number((n||0).toFixed(1));
 const cards=r=>r?.practice?r.practice.deck.map(id=>r.practice.pool.find(c=>c.id===id)).filter(Boolean):null;
 function baseline(container,index){return index>0?cards(container.results[index-1]):container.initialDeck||null;}
 function changes(before,after){if(!before||!after)return null;const group=list=>{const out=new Map();for(const c of list){const id=c.key+':'+!!c.upgraded,g=out.get(id)||{key:c.key,upgraded:!!c.upgraded,count:0};g.count++;out.set(id,g);}return out;},a=group(before),b=group(after);return [...new Set([...a.keys(),...b.keys()])].map(id=>({...b.get(id)||a.get(id),before:a.get(id)?.count||0,after:b.get(id)?.count||0})).filter(c=>c.before!==c.after);}
 function evidence(result,key){return window.BattleInsights.evidence(result,key);}
 function eventScenes(result,changed){
  const actors=result.actors||[],actor=id=>actors.find(a=>a.id===id),name=id=>actor(id)?.name||id||'아군';
  return (result.recap?.events||[]).filter(e=>['heal','shield','protect','counter','ko'].includes(e.kind)&&e.amount>0).map(e=>{
   const attacker=actor(e.actor),target=actor(e.target),failure=e.kind==='ko'&&(target?.side===0||e.target?.startsWith('a'));
   const inferred=['counter','ko'].includes(e.kind)&&e.origin!=='basic'&&(attacker?.side===0||e.actor?.startsWith('a'))&&D.cards[e.key]?e.key:null;
   const key=failure?null:e.cardKey||inferred;
   const label=e.kind==='ko'?(failure?'아군 전투불능'+(e.shared?' · 피해 분담 중':''):'적 처치'):{heal:'위기 회복',shield:'보호막 흡수',protect:'피해 분담',counter:'반격 피해'}[e.kind];
   const source=key?D.cards[key].name:e.origin==='basic'?'기본 행동':e.origin==='enemy'||attacker?.side===1?'적 행동':e.origin==='card'?'카드 출처 미기록':'행동 출처 미기록';
   return {at:e.at,key,failure,related:!!key&&changed.has(key),text:source+' · '+(e.actor?name(e.actor)+' → ':'')+name(e.target)+' · '+label+' '+num(e.amount)};
  });
 }
 function moments(result,changed){return eventScenes(result,changed).filter(e=>!e.failure).sort((a,b)=>Number(b.related)-Number(a.related)||b.at-a.at).slice(0,3);}
 function setbacks(result){return eventScenes(result,new Set()).filter(e=>e.failure).sort((a,b)=>a.at-b.at).slice(0,2);}

 function analyze(result,before){const current=cards(result),delta=changes(before,current),changed=new Set(delta?.filter(c=>c.after>c.before).map(c=>c.key)||[]),keys=[...new Set(current?.map(c=>c.key)||Object.keys(result.stats.cards[0]))];keys.sort((a,b)=>Number(changed.has(b))-Number(changed.has(a))||evidence(result,b).used-evidence(result,a).used);const picks=(changed.size?keys.filter(k=>changed.has(k)):keys.filter(k=>evidence(result,k).used)).slice(0,3);return {current,delta,picks:picks.map(key=>({key,...evidence(result,key)})),traits:before&&current?T.summary(current).map((t,i)=>({...t,old:T.summary(before)[i]})).filter(t=>t.count!==t.old.count):[],moments:moments(result,changed),setbacks:setbacks(result),scenes:(result.traits?.history||[]).slice(-2)};}
 function panel(result,before,origin,index=0){const a=analyze(result,before),name=c=>esc(D.cards[c.key].name)+(c.upgraded?' ✦':'');return `<section class="panel growth-story"><h2>이번 덱이 보여준 변화</h2><p class="result-outcome">${result.winner===0?'승리':esc(result.endReason||'패배')} · ${num(result.time)}초 · 남은 HP ${num(result.hp.reduce((n,h)=>n+h,0))}</p>${result.ultimates?`<p class="note">궁극기 ${result.ultimates.actors.reduce((n,u)=>n+u.casts,0)}회 · 실제 피해 ${num(result.ultimates.history.reduce((n,h)=>n+h.damage,0))} · 카드 명령 ${result.stats.autoCards}회</p>`:''}<p class="note">${index?'직전 교전의 시작 덱':'원정 출발 덱'} 기준 · 이번 교전의 실제 기록</p><div class="deck-delta">${a.delta===null?'<p>이전 덱 기록 없음 · 변경 여부를 비교할 수 없습니다.</p>':!a.delta.length?'<p>카드 구성·진화 변화 없음</p>':a.delta.map(c=>`<span class="chip">${name(c)} ${c.before}→${c.after}장</span>`).join('')}</div>${a.traits.length?`<p class="trait-delta">${a.traits.map(t=>`${esc(t.name)} ${t.old.count}→${t.count}종 · ${t.old.level}→${t.level}단계`).join(' / ')}</p>`:''}<div class="growth-cards">${a.picks.map(c=>`<article>${V.identity(c.key)}<strong>${c.status}</strong><p>${c.parts.length?c.parts.join(' · '):c.used?'효과 수치 미기록 또는 합산되지 않는 지원 · 상세에서 확인':c.status.includes('미기록')?'사용 효과를 확인할 기록 없음':'이번 교전에서 사용 효과 없음'}</p></article>`).join('')||'<p>기록된 카드 사용 없음</p>'}</div>${a.moments.length?`<div class="growth-moments"><strong>아군 기여 장면 · 변경 카드 우선</strong>${a.moments.map(e=>`<p>${num(e.at)}초 · ${esc(e.text)}</p>`).join('')}</div>`:''}${a.setbacks.length?`<div class="growth-setbacks"><strong>아군 전투불능 · 첫 발생 장면</strong>${a.setbacks.map(e=>`<p>${num(e.at)}초 · ${esc(e.text)}</p>`).join('')}</div>`:''}${a.scenes.length?`<div class="growth-scenes"><strong>기록된 특성 장면</strong>${a.scenes.map(e=>`<p>${num(e.at)}초 · ${esc(T.traits[e.trait].name)} · ${esc(e.text)}</p>`).join('')}</div>`:'<p class="note">기록된 특성 장면 없음</p>'}<p class="note">카드별 합산 기록입니다. 진화·사본별 효과는 분리되지 않습니다. 미사용만으로 약한 카드라고 판단할 수 없습니다.</p>${result.practice&&origin?`<button data-action="practice-open" data-origin="${origin}" data-result="${index}">덱 비교 연습</button>`:''}<p class="note">시간·남은 HP와 카드 효과를 함께 비교하세요. 덱 변경으로 난수 소비가 달라져 한 번의 결과가 승리 원인을 증명하지는 않습니다.</p></section>`;}
 function matchDeck(list,pool){if(!Array.isArray(list)||list.length!==20)return null;const ids=[];for(const c of list){const found=pool.find(p=>p.key===c.key&&!!p.upgraded===!!c.upgraded&&!ids.includes(p.id));if(!found)return null;ids.push(found.id);}return D.validateDeck(ids,pool)?null:ids;}
 window.ResultStory={cards,baseline,changes,evidence,analyze,panel,matchDeck,moments,setbacks};
})();
